mod f47_fukui {
    use super::*;
    use std::collections::HashMap;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        ring_classes: HashMap<String, String>,
        candidates: Vec<usize>,
        expected: String,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    fn expected_ok(expected: &str, class: &str) -> bool {
        match expected {
            "ortho_para" => class == "ortho" || class == "para",
            "meta" => class == "meta",
            "beta" => class == "beta",
            _ => false,
        }
    }

    #[test]
    fn f47_eas_ranking_matches_rules() {
        let fixture: Fixture = load("fukui_eas.json");
        let mut correct = 0usize;
        let mut failures = Vec::new();

        for case in &fixture.cases {
            let pos: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();
            let eht = sci_form::eht::solve_eht(&case.elements, &pos, None)
                .unwrap_or_else(|e| panic!("{}: EHT failed: {e}", case.name));
            let fukui = sci_form::reactivity::compute_fukui_descriptors(&case.elements, &pos, &eht);

            // L0: Fukui functions integrate to 1; dual = f+ - f-.
            let sum_m: f64 = fukui.f_minus.iter().sum();
            let sum_p: f64 = fukui.f_plus.iter().sum();
            assert!(
                (sum_m - 1.0).abs() < 1e-9,
                "{}: sum f- = {sum_m}",
                case.name
            );
            assert!(
                (sum_p - 1.0).abs() < 1e-9,
                "{}: sum f+ = {sum_p}",
                case.name
            );
            for (i, d) in fukui.dual_descriptor.iter().enumerate() {
                assert!(
                    (*d - (fukui.f_plus[i] - fukui.f_minus[i])).abs() < 1e-12,
                    "{}: dual inconsistent at atom {i}",
                    case.name
                );
            }

            let top = case
                .candidates
                .iter()
                .max_by(|&&a, &&b| fukui.f_minus[a].partial_cmp(&fukui.f_minus[b]).unwrap())
                .copied()
                .unwrap();
            let class = case.ring_classes.get(&top.to_string()).cloned().unwrap();
            if expected_ok(&case.expected, &class) {
                correct += 1;
            } else {
                failures.push(format!(
                    "{}: top-1 atom {top} is {class}, expected {} (f-={:.3})",
                    case.name, case.expected, fukui.f_minus[top]
                ));
            }
        }

        let fraction = correct as f64 / fixture.cases.len() as f64;
        println!(
            "F47 EAS ranking: {correct}/{} correct (fraction {fraction:.3})",
            fixture.cases.len()
        );
        for f in &failures {
            println!("  MISS: {f}");
        }
        assert!(
            fraction >= 0.8,
            "EAS ranking fraction {fraction:.3} < 0.80 ({correct}/{})",
            fixture.cases.len()
        );
        record(
            "F47",
            "eas_site_ranking",
            "fraction_correct",
            fraction,
            0.8,
            fraction >= 0.8,
            fixture.cases.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F42 — PM3 heat of formation: regression guard (MOPAC cross-check blocked)
// ═══════════════════════════════════════════════════════════════════════════

mod f42_pm3_guard {
    use super::*;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        exp_dhf: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Documented gap: MOPAC parity is blocked (no binary/Fortran toolchain;
    /// see docs/validation/cross-library-validation.es.md §13.3). The PM3
    /// NDDO core needs revalidation against MOPAC before ΔHf can gate on
    /// accuracy. This guard only trips on gross behavioral regressions.
    const KNOWN_GAP_MAX_KCAL: f64 = 5000.0;

    #[test]
    fn f42_pm3_heat_of_formation_guard() {
        let fixture: Fixture = load("pm3_dhf.json");
        let mut worst = (0.0f64, String::new());
        let mut converged = 0usize;

        for case in &fixture.cases {
            let pos: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();
            let res = sci_form::pm3::solve_pm3(&case.elements, &pos)
                .unwrap_or_else(|e| panic!("{}: PM3 failed: {e}", case.name));
            assert!(
                res.heat_of_formation.is_finite(),
                "{}: non-finite ΔHf",
                case.name
            );
            assert!(res.gap > 0.0, "{}: non-positive gap", case.name);
            if res.converged {
                converged += 1;
            }
            let err = (res.heat_of_formation - case.exp_dhf).abs();
            if err > worst.0 {
                worst = (err, case.name.clone());
            }
        }

        println!(
            "F42 PM3 guard: {}/{} converged, max |ΔHf - exp| = {:.1} kcal/mol ({}) — KNOWN GAP (MOPAC parity blocked)",
            converged,
            fixture.cases.len(),
            worst.0,
            worst.1
        );
        assert!(
            worst.0 <= KNOWN_GAP_MAX_KCAL,
            "PM3 ΔHf deviation grew beyond the documented gap: {:.1} kcal/mol for {}",
            worst.0,
            worst.1
        );
        record(
            "F42",
            "pm3_heat_of_formation_guard",
            "max_abs_vs_experiment",
            worst.0,
            KNOWN_GAP_MAX_KCAL,
            worst.0 <= KNOWN_GAP_MAX_KCAL,
            fixture.cases.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F48 — Hessian diagonalization machinery vs xtb vibspectrum
// ═══════════════════════════════════════════════════════════════════════════

mod f48_hessian {
    use super::pyscf_support::positions_angstrom;
    use super::*;
    use nalgebra::DMatrix;
    use sci_form::ir::{build_vibrational_analysis_from_hessian, HessianMethod};

    /// Hartree/Bohr² → eV/Å².
    const HA_BOHR2_TO_EV_ANG2: f64 = 27.211386245988 / (0.529177210903 * 0.529177210903);

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        hessian_hartree_bohr2: Vec<f64>,
        frequencies_cm1: Vec<f64>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    #[test]
    fn f48_hessian_diagonalization_matches_xtb() {
        let fixture: Fixture = load("xtb_hessian.json");
        let mut worst = (0.0f64, String::new());
        let mut total = 0usize;

        for case in &fixture.cases {
            let n = case.elements.len();
            assert_eq!(
                case.hessian_hartree_bohr2.len(),
                9 * n * n,
                "{}: Hessian size",
                case.name
            );
            let positions = positions_angstrom(&case.coords);
            let hessian = DMatrix::from_row_slice(
                3 * n,
                3 * n,
                &case
                    .hessian_hartree_bohr2
                    .iter()
                    .map(|v| v * HA_BOHR2_TO_EV_ANG2)
                    .collect::<Vec<_>>(),
            );

            let analysis = build_vibrational_analysis_from_hessian(
                &case.elements,
                &positions,
                &hessian,
                HessianMethod::Eht,
                0.005,
                None,
            )
            .unwrap_or_else(|e| panic!("{}: analysis failed: {e}", case.name));

            let mut ours: Vec<f64> = analysis
                .modes
                .iter()
                .filter(|m| m.is_real)
                .map(|m| m.frequency_cm1)
                .collect();
            ours.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let mut reference: Vec<f64> = case
                .frequencies_cm1
                .iter()
                .filter(|f| **f > 1.0)
                .copied()
                .collect();
            reference.sort_by(|a, b| a.partial_cmp(b).unwrap());
            assert_eq!(
                ours.len(),
                reference.len(),
                "{}: real mode count {} != {}",
                case.name,
                ours.len(),
                reference.len()
            );

            for (k, (o, r)) in ours.iter().zip(reference.iter()).enumerate() {
                let diff = (o - r).abs();
                total += 1;
                if diff > worst.0 {
                    worst = (diff, format!("{} mode {}", case.name, k + 1));
                }
            }
        }

        println!(
            "F48 vs xtb vibspectrum: {total} frequencies, max |Δν| = {:.4} cm⁻¹ ({})",
            worst.0, worst.1
        );
        assert!(
            worst.0 <= 2.0,
            "frequency max error {:.4} cm⁻¹ for {}",
            worst.0,
            worst.1
        );
        record(
            "F48",
            "hessian_diagonalization_vs_xtb",
            "max_abs",
            worst.0,
            2.0,
            worst.0 <= 2.0,
            total,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F26 — SCF Mulliken dipoles vs PySCF (parity + point-charge gap + NIST)
// ═══════════════════════════════════════════════════════════════════════════

mod f26_dipole {
    use super::pyscf_support::*;
    use super::*;
    use sci_form::scf::scf_loop::{run_scf, ScfConfig};
    use sci_form::scf::types::MolecularSystem;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        dipole_exact: Vec<f64>,
        dipole_mulliken: Vec<f64>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// NIST experimental gas-phase dipoles (Debye) for the fixture set.
    fn nist_dipole(name: &str) -> Option<f64> {
        match name {
            "H2" => Some(0.0),
            "H2O" => Some(1.85),
            "CH4" => Some(0.0),
            "NH3" => Some(1.47),
            "HF" => Some(1.73),
            "CO" => Some(0.11),
            "C2H4" => Some(0.0),
            "CH2O" => Some(2.33),
            "PH3" => Some(0.57),
            "H2S" => Some(0.97),
            "HCl" => Some(1.08),
            _ => None,
        }
    }

    fn norm(v: &[f64]) -> f64 {
        v.iter().map(|x| x * x).sum::<f64>().sqrt()
    }

    #[test]
    fn f26_dipole_matches_pyscf() {
        let fixture: Fixture = load("pyscf_scf.json");
        let mut worst_parity = (0.0f64, String::new());
        let mut worst_angle = (0.0f64, String::new());
        let mut worst_gap = (0.0f64, String::new());
        let mut nist_ok = 0usize;
        let mut nist_n = 0usize;

        for case in &fixture.cases {
            let positions = positions_angstrom(&case.coords);
            let system = MolecularSystem::from_angstrom(&case.elements, &positions, 0, 1);
            let result = run_scf(&system, &ScfConfig::default());
            assert!(result.converged, "{}: SCF did not converge", case.name);

            // Our dipole from our SCF Mulliken charges (point-charge formula).
            let dip = sci_form::dipole::compute_dipole(&result.mulliken_charges, &positions);
            assert_eq!(dip.vector.len(), 3);

            // (a) Parity with PySCF's Mulliken point-charge dipole.
            for k in 0..3 {
                let d = (dip.vector[k] - case.dipole_mulliken[k]).abs();
                if d > worst_parity.0 {
                    worst_parity = (d, format!("{}[{k}]", case.name));
                }
            }
            // Direction agreement (angle between vectors, degrees).
            let (a, b) = (&dip.vector, &case.dipole_mulliken);
            if norm(a) > 1e-9 && norm(b) > 1e-9 {
                let cos = (a[0] * b[0] + a[1] * b[1] + a[2] * b[2]) / norm(a) / norm(b);
                let angle = cos.clamp(-1.0, 1.0).acos().to_degrees();
                if angle > worst_angle.0 {
                    worst_angle = (angle, case.name.clone());
                }
            }

            // (b) Point-charge gap vs the exact-density dipole (documents the
            // approximation; not gated).
            let gap = (norm(&dip.vector) - norm(&case.dipole_exact)).abs();
            if gap > worst_gap.0 {
                worst_gap = (gap, case.name.clone());
            }

            // (c) NIST experimental magnitude (informational; STO-3G method
            // error dominates, so only counted, not gated).
            if let Some(exp) = nist_dipole(&case.name) {
                nist_n += 1;
                let ours = norm(&dip.vector);
                let ok = if exp < 0.1 {
                    (ours - exp).abs() < 1.0
                } else {
                    (ours - exp).abs() / exp < 0.5
                };
                if ok {
                    nist_ok += 1;
                }
            }
        }

        println!(
            "F26 vs PySCF: parity max |Δμ| = {:.3e} D ({}), direction max = {:.4}° ({}); point-charge gap max = {:.3} D ({}); NIST (STO-3G) {}/{} within 50%",
            worst_parity.0,
            worst_parity.1,
            worst_angle.0,
            worst_angle.1,
            worst_gap.0,
            worst_gap.1,
            nist_ok,
            nist_n
        );
        assert!(
            worst_parity.0 <= 1e-6,
            "dipole parity max error {:.3e} D for {}",
            worst_parity.0,
            worst_parity.1
        );
        assert!(
            worst_angle.0 <= 1e-4,
            "dipole direction max error {:.4}° for {}",
            worst_angle.0,
            worst_angle.1
        );
        record(
            "F26",
            "scf_mulliken_dipole_parity_debye",
            "max_abs",
            worst_parity.0,
            1e-6,
            worst_parity.0 <= 1e-6,
            fixture.cases.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F49 — IR group assignment vs NIST/CCCBDB + spectrum machinery (L0)
// ═══════════════════════════════════════════════════════════════════════════

mod f49_ir {
    use super::*;
    use nalgebra::DMatrix;
    use sci_form::ir::{
        build_vibrational_analysis_from_hessian, compute_ir_spectrum,
        peak_assignment::assign_peaks, HessianMethod,
    };
    use std::collections::HashMap;
    use std::path::PathBuf;

    const HA_BOHR2_TO_EV_ANG2: f64 = 27.211386245988 / (0.529177210903 * 0.529177210903);

    #[derive(Deserialize)]
    struct ExpMol {
        elements: Vec<u8>,
        experimental: Option<ExpData>,
    }

    #[derive(Deserialize)]
    struct ExpData {
        ir_frequencies_cm1: Option<Vec<f64>>,
    }

    #[derive(Deserialize)]
    struct ExpFile {
        molecules: HashMap<String, ExpMol>,
    }

    #[derive(Deserialize)]
    struct HCase {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        hessian_hartree_bohr2: Vec<f64>,
    }

    #[derive(Deserialize)]
    struct HFix {
        cases: Vec<HCase>,
    }

    fn load_fixture<T: for<'de> Deserialize<'de>>(rel: &str) -> T {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("fixtures")
            .join(rel);
        let data = std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("missing fixture {} ({err})", path.display()));
        serde_json::from_str(&data).expect("invalid fixture JSON")
    }

    /// (molecule key in experimental_reference.json, expected group substring)
    const EXPECTED: &[(&str, &str)] = &[
        ("H2", "H-H"),
        ("H2O", "O-H"),
        ("CH4", "C-H"),
        ("NH3", "N-H"),
        ("HF_molecule", "H-F"),
        ("CO", "C≡O"),
        ("C2H4", "C=C"),
        ("benzene", "C=C"),
        ("formaldehyde", "C=O"),
    ];

    #[test]
    fn f49_ir_assignment_matches_nist() {
        let exp: ExpFile = load_fixture("experimental_reference.json");
        let mut hits = 0usize;
        let mut total = 0usize;

        for (key, want) in EXPECTED {
            let mol = exp
                .molecules
                .get(*key)
                .unwrap_or_else(|| panic!("{key}: missing from experimental_reference.json"));
            let freqs = mol
                .experimental
                .as_ref()
                .and_then(|e| e.ir_frequencies_cm1.clone())
                .unwrap_or_else(|| panic!("{key}: no IR frequencies"));
            assert!(!freqs.is_empty(), "{key}: empty IR list");
            let unit = vec![1.0; freqs.len()];
            let result = assign_peaks(&freqs, &unit, &mol.elements, None);
            total += 1;
            let found = result.functional_groups.iter().any(|g| g.contains(want));
            if found {
                hits += 1;
            } else {
                println!(
                    "F49 MISS {key}: want '{want}' in {:?} (freqs {freqs:?})",
                    result.functional_groups
                );
            }
        }

        // S-H group (new in this validation round): xtb-GFN2 H2S stretches
        // at 2478/2483 cm-1 must land in the widened S-H window.
        let hess: HFix = load_fixture("validation/xtb_hessian.json");
        let h2s = hess
            .cases
            .iter()
            .find(|c| c.name == "hydrogen sulfide")
            .expect("H2S case in xtb_hessian.json");
        let n = h2s.elements.len();
        let positions: Vec<[f64; 3]> = h2s
            .coords
            .chunks_exact(3)
            .map(|c| [c[0], c[1], c[2]])
            .collect();
        let hessian = DMatrix::from_row_slice(
            3 * n,
            3 * n,
            &h2s.hessian_hartree_bohr2
                .iter()
                .map(|v| v * HA_BOHR2_TO_EV_ANG2)
                .collect::<Vec<_>>(),
        );
        let analysis = build_vibrational_analysis_from_hessian(
            &h2s.elements,
            &positions,
            &hessian,
            HessianMethod::Eht,
            0.005,
            None,
        )
        .expect("H2S analysis");
        let real_freqs: Vec<f64> = analysis
            .modes
            .iter()
            .filter(|m| m.is_real)
            .map(|m| m.frequency_cm1)
            .collect();
        let unit = vec![1.0; real_freqs.len()];
        let sh = assign_peaks(&real_freqs, &unit, &h2s.elements, None);
        total += 1;
        if sh.functional_groups.iter().any(|g| g.contains("S-H")) {
            hits += 1;
        } else {
            println!(
                "F49 MISS H2S: want 'S-H' in {:?} (freqs {real_freqs:.1?})",
                sh.functional_groups
            );
        }

        let recall = hits as f64 / total as f64;
        println!("F49 vs NIST/CCCBDB: group recall {hits}/{total} = {recall:.3}");

        // ── Spectrum machinery (L0): water spectrum from the xtb Hessian ──
        let water = hess
            .cases
            .iter()
            .find(|c| c.name == "water")
            .expect("water case in xtb_hessian.json");
        let nw = water.elements.len();
        let wpos: Vec<[f64; 3]> = water
            .coords
            .chunks_exact(3)
            .map(|c| [c[0], c[1], c[2]])
            .collect();
        let whess = DMatrix::from_row_slice(
            3 * nw,
            3 * nw,
            &water
                .hessian_hartree_bohr2
                .iter()
                .map(|v| v * HA_BOHR2_TO_EV_ANG2)
                .collect::<Vec<_>>(),
        );
        let wanalysis = build_vibrational_analysis_from_hessian(
            &water.elements,
            &wpos,
            &whess,
            HessianMethod::Eht,
            0.005,
            None,
        )
        .expect("water analysis");
        let spectrum = compute_ir_spectrum(&wanalysis, 20.0, 400.0, 4000.0, 361);
        assert!(
            spectrum
                .intensities
                .iter()
                .all(|v| v.is_finite() && *v >= 0.0),
            "spectrum must be finite and non-negative"
        );
        let n_real = wanalysis.modes.iter().filter(|m| m.is_real).count();
        assert_eq!(spectrum.peaks.len(), n_real, "one peak per real mode");
        // Lorentzian integrates to 1: grid integral ≈ Σ mode intensities.
        let step = spectrum.wavenumbers[1] - spectrum.wavenumbers[0];
        let integral: f64 = spectrum.intensities.iter().sum::<f64>() * step;
        let mode_sum: f64 = wanalysis
            .modes
            .iter()
            .filter(|m| m.is_real)
            .map(|m| m.ir_intensity)
            .sum();
        if mode_sum > 0.0 {
            let rel = ((integral - mode_sum) / mode_sum).abs();
            println!("F49 spectrum L0: integral {integral:.4} vs ΣI {mode_sum:.4} (rel {rel:.4})");
            assert!(rel <= 0.05, "broadened integral must match ΣI within 5%");
        }
        // Spectrum maximum sits on the strongest mode (within γ).
        let (imax, _) = spectrum
            .intensities
            .iter()
            .enumerate()
            .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
            .unwrap();
        let strongest = spectrum
            .peaks
            .iter()
            .max_by(|a, b| a.ir_intensity.partial_cmp(&b.ir_intensity).unwrap())
            .unwrap();
        let dmax = (spectrum.wavenumbers[imax] - strongest.frequency_cm1).abs();
        assert!(
            dmax <= 20.0,
            "spectrum max must sit on the strongest mode (Δ={dmax:.1})"
        );

        assert!(
            recall >= 0.9,
            "IR group recall {recall:.3} below 0.90 ({hits}/{total})"
        );
        record(
            "F49",
            "ir_group_recall_vs_nist",
            "recall",
            recall,
            0.9,
            recall >= 0.9,
            total,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F70 — Framework optimization (BFGS+UFF) vs RDKit UFF minimization
// ═══════════════════════════════════════════════════════════════════════════

mod f70_framework_opt {
    use super::*;
    use sci_form::materials::geometry_opt::{optimize_framework, FrameworkOptConfig, OptMethod};

    #[derive(Deserialize)]
    struct Case {
        name: String,
        smiles: String,
        elements: Vec<u8>,
        initial_coords: Vec<f64>,
        e_initial: f64,
        optimized_coords: Vec<f64>,
        e_final: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// kcal/mol/A: plan's 0.01 eV/A max-force gate, tightened 20x.
    const MAX_FORCE_TOL: f64 = 0.01;
    /// kcal/mol/atom energy agreement (plan: 1e-6 eV/atom = 2.3e-5 kcal/mol).
    const ENERGY_TOL: f64 = 1e-6;

    #[test]
    fn f70_framework_opt_matches_rdkit() {
        let fixture: Fixture = load("uff_opt.json");
        let mut worst_de = (0.0f64, String::new());
        let mut worst_rmsd = (0.0f64, String::new());
        let mut worst_force = (0.0f64, String::new());

        for case in &fixture.cases {
            let mol = sci_form::graph::Molecule::from_smiles(&case.smiles)
                .unwrap_or_else(|e| panic!("{}: {e}", case.name));
            assert_eq!(
                mol.graph.node_count(),
                case.elements.len(),
                "{}: atom count",
                case.name
            );
            let ff = sci_form::forcefield::builder::build_uff_force_field(&mol);
            let pos0: Vec<[f64; 3]> = case
                .initial_coords
                .chunks_exact(3)
                .map(|w| [w[0], w[1], w[2]])
                .collect();

            // Same surface check (F16 contract) at the starting geometry.
            let flat0: Vec<f64> = pos0.iter().flat_map(|p| p.iter().copied()).collect();
            let mut g0 = vec![0.0; flat0.len()];
            let e0 = ff.compute_system_energy_and_gradients(&flat0, &mut g0);
            assert!(
                (e0 - case.e_initial).abs() < 1e-6,
                "{}: starting energy ours={e0:.6} rdkit={:.6}",
                case.name,
                case.e_initial
            );

            let closure = move |_el: &[u8],
                                pos: &[[f64; 3]]|
                  -> Result<(f64, Vec<[f64; 3]>), String> {
                let flat: Vec<f64> = pos.iter().flat_map(|p| p.iter().copied()).collect();
                let mut g = vec![0.0; flat.len()];
                let e = ff.compute_system_energy_and_gradients(&flat, &mut g);
                let f: Vec<[f64; 3]> = g.chunks_exact(3).map(|w| [-w[0], -w[1], -w[2]]).collect();
                Ok((e, f))
            };
            let config = FrameworkOptConfig {
                method: OptMethod::Bfgs,
                max_iter: 2000,
                force_tol: 1e-4,
                energy_tol: 1e-12,
                ..Default::default()
            };
            let result = optimize_framework(&case.elements, &pos0, &closure, &config)
                .unwrap_or_else(|e| panic!("{}: {e}", case.name));
            assert!(result.converged, "{}: BFGS did not converge", case.name);
            assert!(
                result.energy <= e0,
                "{}: energy increased {e0:.4} -> {:.4}",
                case.name,
                result.energy
            );

            let n = case.elements.len() as f64;
            let de = ((result.energy - case.e_final) / n).abs();
            if de > worst_de.0 {
                worst_de = (de, case.name.clone());
            }
            let flat: Vec<f64> = result
                .positions
                .iter()
                .flat_map(|p| p.iter().copied())
                .collect();
            let rmsd = sci_form::alignment::kabsch::compute_rmsd(&flat, &case.optimized_coords);
            if rmsd > worst_rmsd.0 {
                worst_rmsd = (rmsd, case.name.clone());
            }
            if result.max_force > worst_force.0 {
                worst_force = (result.max_force, case.name.clone());
            }

            // No atom crossings (plan: min distance >= 0.7 A).
            let mut mind = f64::INFINITY;
            for (i, a) in result.positions.iter().enumerate() {
                for b in result.positions.iter().skip(i + 1) {
                    let d = ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2))
                        .sqrt();
                    mind = mind.min(d);
                }
            }
            assert!(
                mind >= 0.7,
                "{}: atoms collapsed (min dist {mind:.3} A)",
                case.name
            );
        }

        println!(
            "F70 vs RDKit UFF-opt: {} molecules, worst |ΔE|/atom = {:.3e} kcal/mol ({}), worst RMSD = {:.2e} A ({}), worst max force = {:.2e} kcal/mol/A ({})",
            fixture.cases.len(),
            worst_de.0,
            worst_de.1,
            worst_rmsd.0,
            worst_rmsd.1,
            worst_force.0,
            worst_force.1
        );
        assert!(
            worst_de.0 <= ENERGY_TOL,
            "energy agreement {:.3e} above tol",
            worst_de.0
        );
        assert!(
            worst_rmsd.0 <= 0.01,
            "geometry RMSD {:.3e} A above tol",
            worst_rmsd.0
        );
        assert!(
            worst_force.0 <= MAX_FORCE_TOL,
            "max force {:.3e} above tol",
            worst_force.0
        );
        record(
            "F70",
            "uff_opt_energy_vs_rdkit",
            "max_abs",
            worst_de.0,
            ENERGY_TOL,
            worst_de.0 <= ENERGY_TOL,
            fixture.cases.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F67 — Framework topologies vs RCSR/pormake + MOF-5 assembly vs pormake
// ═══════════════════════════════════════════════════════════════════════════

mod f67_assembly {
    use super::*;
    use sci_form::materials::assembly::{assemble_framework, Topology};
    use sci_form::materials::cell::UnitCell;
    use sci_form::materials::sbu::Sbu;
    use std::collections::{BTreeMap, HashMap};

    #[derive(Deserialize)]
    struct CgdNode {
        cn: u8,
    }

    #[derive(Deserialize)]
    struct CgdNet {
        cgd: Option<String>,
        nodes: Option<Vec<CgdNode>>,
    }

    #[derive(Deserialize)]
    struct Bb {
        elements: Vec<u8>,
        positions: Vec<[f64; 3]>,
    }

    #[derive(Deserialize)]
    struct Mof5 {
        cell_lengths: Vec<f64>,
        n_atoms: usize,
        composition: HashMap<String, usize>,
        n_bonds: usize,
    }

    #[derive(Deserialize)]
    struct Fixture {
        topologies: HashMap<String, CgdNet>,
        mof5: Mof5,
        node_bb: Bb,
        edge_bb: Bb,
    }

    /// Expected RCSR coordination sets (RCSR database: Blatov/O'Keeffe).
    fn expected_degrees(name: &str) -> Vec<u8> {
        match name {
            "pcu" => vec![6],
            "dia" => vec![4, 4],
            "sql" => vec![4],
            "bcu" => vec![8, 8],
            "fcu" => vec![12, 12, 12, 12],
            "nbo" => vec![4, 4],
            "pts" => vec![4, 4],
            "kgm" => vec![4, 4, 4],
            "hxl" => vec![6],
            "pillared_sql" => vec![6],
            _ => panic!("unknown net {name}"),
        }
    }

    fn topology_by_name(name: &str) -> Topology {
        match name {
            "pcu" => Topology::pcu(),
            "dia" => Topology::dia(),
            "sql" => Topology::sql(),
            "bcu" => Topology::bcu(),
            "fcu" => Topology::fcu(),
            "nbo" => Topology::nbo(),
            "pts" => Topology::pts(),
            "kgm" => Topology::kgm(),
            "hxl" => Topology::hxl(),
            "pillared_sql" => Topology::pillared_sql(),
            _ => panic!("unknown net {name}"),
        }
    }

    fn degrees(topo: &Topology) -> Vec<u8> {
        let mut deg = vec![0u8; topo.nodes.len()];
        for &(a, b, off) in &topo.edges {
            if a == b && off == [0, 0, 0] {
                continue;
            }
            if a == b {
                deg[a] += 2;
            } else {
                deg[a] += 1;
                deg[b] += 1;
            }
        }
        let mut sorted = deg;
        sorted.sort_unstable();
        sorted
    }

    #[test]
    fn f67_topology_degrees_match_rcsr() {
        let fixture: Fixture = load("pormake_mof.json");
        let mut mismatches = 0usize;
        let mut total = 0usize;

        for name in [
            "pcu",
            "dia",
            "sql",
            "bcu",
            "fcu",
            "nbo",
            "pts",
            "kgm",
            "hxl",
            "pillared_sql",
        ] {
            let topo = topology_by_name(name);
            let ours = degrees(&topo);
            let expected = expected_degrees(name);
            total += 1;
            if ours != expected {
                mismatches += 1;
                println!("F67 MISMATCH {name}: ours={ours:?} RCSR={expected:?}");
            }
            // Cross-check against pormake's .cgd coordination where the
            // file exists and describes the same net.
            if let Some(net) = fixture.topologies.get(name) {
                if net.cgd.is_some() {
                    if let Some(nodes) = &net.nodes {
                        let mut cgd_cn: Vec<u8> = nodes.iter().map(|n| n.cn).collect();
                        cgd_cn.sort_unstable();
                        // Known divergence: pormake's kag.cgd carries a
                        // pillaring c-edge (6-c), while RCSR kag and our
                        // kgm are the 4-c kagome layer.
                        if name == "kgm" {
                            assert_eq!(cgd_cn, vec![6], "pormake kag.cgd coordination changed?");
                            println!(
                                "F67 note: pormake kag.cgd is 6-c (pillared variant); RCSR kag / our kgm are 4-c"
                            );
                        } else {
                            // .cgd lists symmetry-unique nodes while our
                            // cell choice may repeat them: compare the
                            // unique coordination sets.
                            let mut ours_u = ours.clone();
                            ours_u.dedup();
                            cgd_cn.dedup();
                            total += 1;
                            if ours_u != cgd_cn {
                                mismatches += 1;
                                println!(
                                    "F67 MISMATCH {name}: ours={ours_u:?} pormake-cgd={cgd_cn:?}"
                                );
                            }
                        }
                    }
                }
            }
        }

        println!("F67 topology degrees: {total} checks, {mismatches} mismatches");
        assert_eq!(mismatches, 0, "topology degree mismatches");
        record(
            "F67",
            "topology_degree_mismatches",
            "mismatches",
            mismatches as f64,
            0.0,
            mismatches == 0,
            total,
        );
    }

    #[test]
    fn f67_mof5_assembly_matches_pormake() {
        let fixture: Fixture = load("pormake_mof.json");
        let mut node = Sbu::new("Zn4O");
        for (z, p) in fixture
            .node_bb
            .elements
            .iter()
            .zip(fixture.node_bb.positions.iter())
        {
            node.add_atom(*z, *p);
        }
        let mut edge = Sbu::new("phenylene");
        for (z, p) in fixture
            .edge_bb
            .elements
            .iter()
            .zip(fixture.edge_bb.positions.iter())
        {
            edge.add_atom(*z, *p);
        }

        let cell = UnitCell::cubic(fixture.mof5.cell_lengths[0]);
        let built = assemble_framework(&node, &edge, &Topology::pcu(), &cell);

        // Same building blocks + same cell -> same structure.
        assert_eq!(
            built.atoms.len(),
            fixture.mof5.n_atoms,
            "atom count vs pormake"
        );
        let mut comp: BTreeMap<u8, usize> = BTreeMap::new();
        for atom in &built.atoms {
            *comp.entry(atom.element).or_insert(0) += 1;
        }
        let z_of = |sym: &str| match sym {
            "H" => 1,
            "C" => 6,
            "O" => 8,
            "Zn" => 30,
            _ => panic!("unexpected element {sym}"),
        };
        for (sym, count) in &fixture.mof5.composition {
            assert_eq!(
                comp.get(&z_of(sym)),
                Some(count),
                "composition element {sym}"
            );
        }

        // Node-linker junctions must meet at bonding distance (pormake
        // fuses X connection points into bonds; our placer must land the
        // blocks in contact, not overlapping nor detached).
        let cart = |frac: [f64; 3]| cell.frac_to_cart(frac);
        let node0: Vec<[f64; 3]> = built
            .atoms
            .iter()
            .zip(built.labels.iter())
            .filter(|(_, label)| *label == "node_0")
            .map(|(atom, _)| cart(atom.frac_coords))
            .collect();
        let linker0: Vec<[f64; 3]> = built
            .atoms
            .iter()
            .zip(built.labels.iter())
            .filter(|(_, label)| *label == "linker_0")
            .map(|(atom, _)| cart(atom.frac_coords))
            .collect();
        assert_eq!(node0.len(), node.num_atoms());
        assert_eq!(linker0.len(), edge.num_atoms());
        let mut junction_min = f64::INFINITY;
        for p in &node0 {
            for q in &linker0 {
                let dist =
                    ((p[0] - q[0]).powi(2) + (p[1] - q[1]).powi(2) + (p[2] - q[2]).powi(2)).sqrt();
                junction_min = junction_min.min(dist);
            }
        }
        println!("F67 MOF-5 junction min distance: {junction_min:.3} A");
        assert!(
            (0.9..2.2).contains(&junction_min),
            "junction must be a bond, got {junction_min:.3} A"
        );

        // No collapsed/overlapping atoms anywhere (minimum image).
        let all: Vec<[f64; 3]> = built.atoms.iter().map(|a| cart(a.frac_coords)).collect();
        let mut global_min = f64::INFINITY;
        for (i, p) in all.iter().enumerate() {
            for q in all.iter().skip(i + 1) {
                let mut dist2 = 0.0;
                for k in 0..3 {
                    let mut delta = (p[k] - q[k]) / fixture.mof5.cell_lengths[0];
                    delta -= delta.round();
                    dist2 += (delta * fixture.mof5.cell_lengths[0]).powi(2);
                }
                global_min = global_min.min(dist2.sqrt());
            }
        }
        assert!(
            global_min >= 0.7,
            "overlapping atoms (min {global_min:.3} A)"
        );

        record(
            "F67",
            "mof5_assembly_vs_pormake",
            "max_abs",
            0.0,
            0.0,
            true,
            1,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F68 — Geometric porosity vs pyzeo (Zeo++ engine) + analytic cases
// ═══════════════════════════════════════════════════════════════════════════

mod f68_porosity {
    use super::*;
    use sci_form::materials::assembly::{assemble_framework, Topology};
    use sci_form::materials::cell::UnitCell;
    use sci_form::materials::sbu::Sbu;

    #[derive(Deserialize)]
    struct Bb {
        elements: Vec<u8>,
        positions: Vec<[f64; 3]>,
    }

    #[derive(Deserialize)]
    struct Mof5 {
        cell_lengths: Vec<f64>,
        cif: String,
    }

    #[derive(Deserialize)]
    struct Pyzeo {
        #[serde(rename = "vf_probe_0.0")]
        vf_probe_0: f64,
        #[serde(rename = "vf_probe_1.2")]
        vf_probe_1_2: f64,
        lcd_diameter: f64,
        pld_diameter: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        mof5: Mof5,
        node_bb: Bb,
        edge_bb: Bb,
        pyzeo: Pyzeo,
    }

    fn elements_of(sites: &[sci_form::materials::cif::CifAtomSite]) -> Vec<u8> {
        sites.iter().map(|site| site.atomic_number).collect()
    }

    fn frac_of(site: &sci_form::materials::cif::CifAtomSite) -> [f64; 3] {
        [site.frac_x, site.frac_y, site.frac_z]
    }

    #[test]
    fn f68_porosity_matches_pyzeo() {
        // ── Analytic cases (no reference program needed) ──
        // Empty cell: all void.
        let empty = UnitCell::cubic(10.0);
        let result = sci_form::materials::compute_porosity(&empty, &[], &[], 0.0, 0.5);
        assert_eq!(result.porosity, 1.0, "empty cell must be fully void");
        assert_eq!(result.pore_volume, 1000.0);

        // Single carbon (r=1.7) at the center of a 20 A cube, probe 0:
        // VF = 1 - 4/3 pi r^3 / V; LCD corner-to-surface x2.
        let cell = UnitCell::cubic(20.0);
        let one =
            sci_form::materials::compute_porosity(&cell, &[6u8], &[[0.5, 0.5, 0.5]], 0.0, 0.2);
        let vf_exact = 1.0 - 4.0 / 3.0 * std::f64::consts::PI * 1.7f64.powi(3) / 8000.0;
        assert!(
            (one.porosity - vf_exact).abs() <= 2e-3,
            "single-atom VF {} vs exact {vf_exact:.5}",
            one.porosity
        );
        let lcd_exact = 2.0 * (300.0f64.sqrt() - 1.7);
        assert!(
            (one.largest_cavity_diameter - lcd_exact).abs() <= 0.35,
            "single-atom LCD {} vs exact {lcd_exact:.3}",
            one.largest_cavity_diameter
        );

        // ── MOF-5 vs pyzeo (same CIF, same radii, probe 0) ──
        // Fine grid for VF/LCD; coarser grid for the PLD bisection
        // (9+ full grid evaluations — resolution still within tol).
        let fixture: Fixture = load("pormake_mof.json");
        let parsed = sci_form::materials::parse_cif(&fixture.mof5.cif)
            .expect("pormake MOF-5 CIF must parse");
        assert_eq!(parsed.atom_sites.len(), 53, "MOF-5 primitive content");
        let elements = elements_of(&parsed.atom_sites);
        let fracs: Vec<[f64; 3]> = parsed.atom_sites.iter().map(frac_of).collect();
        let (_, vf0, lcd0) =
            sci_form::materials::porosity_grid_stats(&parsed.cell, &elements, &fracs, 0.0, 0.25);
        let pld0 =
            sci_form::materials::pore_limiting_diameter(&parsed.cell, &elements, &fracs, 0.35);
        println!(
            "F68 pormake-MOF-5: ours VF={:.4} (ref {:.5}), LCD={:.3} (ref {:.3}), PLD={:.3} (ref {:.3})",
            vf0,
            fixture.pyzeo.vf_probe_0,
            lcd0,
            fixture.pyzeo.lcd_diameter,
            pld0,
            fixture.pyzeo.pld_diameter
        );
        let dvf = (vf0 - fixture.pyzeo.vf_probe_0).abs();
        let dlcd = (lcd0 - fixture.pyzeo.lcd_diameter).abs();
        let dpld = (pld0 - fixture.pyzeo.pld_diameter).abs();
        assert!(dvf <= 0.01, "VF error {dvf:.4}");
        assert!(dlcd <= 0.3, "LCD error {dlcd:.3} A");
        assert!(dpld <= 0.5, "PLD error {dpld:.3} A");

        // ── Same observables on OUR assembly (end-to-end F67+F68) ──
        let mut node = Sbu::new("Zn4O");
        for (z, p) in fixture
            .node_bb
            .elements
            .iter()
            .zip(fixture.node_bb.positions.iter())
        {
            node.add_atom(*z, *p);
        }
        let mut edge = Sbu::new("phenylene");
        for (z, p) in fixture
            .edge_bb
            .elements
            .iter()
            .zip(fixture.edge_bb.positions.iter())
        {
            edge.add_atom(*z, *p);
        }
        let ours_cell = UnitCell::cubic(fixture.mof5.cell_lengths[0]);
        let built = assemble_framework(&node, &edge, &Topology::pcu(), &ours_cell);
        let built_elements: Vec<u8> = built.atoms.iter().map(|a| a.element).collect();
        let built_fracs: Vec<[f64; 3]> = built.atoms.iter().map(|a| a.frac_coords).collect();
        let (_, ours_vf, ours_lcd) = sci_form::materials::porosity_grid_stats(
            &ours_cell,
            &built_elements,
            &built_fracs,
            0.0,
            0.25,
        );
        let ours_pld = sci_form::materials::pore_limiting_diameter(
            &ours_cell,
            &built_elements,
            &built_fracs,
            0.35,
        );
        println!(
            "F68 our-assembly: VF={:.4}, LCD={:.3}, PLD={:.3}",
            ours_vf, ours_lcd, ours_pld
        );
        assert!(
            (ours_vf - fixture.pyzeo.vf_probe_0).abs() <= 0.01,
            "our-assembly VF error"
        );
        assert!(
            (ours_lcd - fixture.pyzeo.lcd_diameter).abs() <= 0.3,
            "our-assembly LCD error"
        );
        assert!(
            (ours_pld - fixture.pyzeo.pld_diameter).abs() <= 0.5,
            "our-assembly PLD error"
        );

        // Probe-1.2 cross-check on the pormake structure (PLD-free
        // core: the limiting diameter is probe-independent).
        let (_, vf12, _) =
            sci_form::materials::porosity_grid_stats(&parsed.cell, &elements, &fracs, 1.2, 0.25);
        let dvf12 = (vf12 - fixture.pyzeo.vf_probe_1_2).abs();
        println!(
            "F68 probe-1.2: ours VF={:.4} (ref {:.5})",
            vf12, fixture.pyzeo.vf_probe_1_2
        );
        assert!(dvf12 <= 0.01, "probe-1.2 VF error {dvf12:.4}");

        record(
            "F68",
            "mof5_porosity_vf_vs_pyzeo",
            "max_abs",
            dvf,
            0.01,
            dvf <= 0.01,
            1,
        );
        record(
            "F68",
            "mof5_porosity_lcd_vs_pyzeo",
            "max_abs",
            dlcd,
            0.3,
            dlcd <= 0.3,
            1,
        );
        record(
            "F68",
            "mof5_porosity_pld_vs_pyzeo",
            "max_abs",
            dpld,
            0.5,
            dpld <= 0.5,
            1,
        );
    }
}
